import {emptyProject,validateProject} from '../../web-studio/model.js';
import {newSynth} from '../../web-studio/instruments.js';
export function noteProject(){const p=emptyProject(),t=p.tracks[0];p.name='Note Proof';p.returns=[];p.sceneNames=['Intro','Lift','Breakdown','Return'];t.id='lead';t.name='Lead';t.volume=.4;t.instrument=newSynth('Init');t.slots[0]='phrase';p.clips.phrase={id:'phrase',kind:'midi',name:'Phrase',sourceBpm:120,beats:8,notes:[{pitch:60,start:.1,duration:.4,velocity:.4,releaseVelocity:.1},{pitch:64,start:1.1,duration:.4,velocity:.55,releaseVelocity:.2,active:false},{pitch:67,start:2.1,duration:.4,velocity:.7,releaseVelocity:.3},{pitch:72,start:3.1,duration:.4,velocity:.45,releaseVelocity:.4}]};p.arrangement=[{id:'phrase-region',trackId:'lead',clipId:'phrase',start:0,length:8,offset:0}];return validateProject(p);}
export const notePrompt='In the existing Phrase MIDI clip, quantize only note array indices 0 and 2 to a 0.25-beat grid at full strength. Transpose those two notes up 12 semitones and reduce their normalized velocities by 0.1. Duplicate those edited notes so the copied phrase starts at zero-based beat 5. Preserve every other note, activation, release velocity, clip length and Arrangement position. Then show the copied notes in the Arrangement Clip view. Do not create tracks, regenerate the clip, play or export.';
export const noteActions=[{type:'notes',args:{clipId:'phrase',action:'quantize',indices:[0,2],grid:.25,strength:1}},{type:'notes',args:{clipId:'phrase',action:'transpose',indices:[0,2],amount:12}},{type:'notes',args:{clipId:'phrase',action:'velocity',indices:[0,2],amount:-.1}},{type:'notes',args:{clipId:'phrase',action:'duplicate',indices:[0,2],at:5}},{type:'command',args:{name:'select',args:{target:'notes',regionId:'phrase-region',where:{start:5,end:8}}}}];
